/* RSS HTML preview only; real RSS XML is generated by the offline builder. */
(async () => {
  'use strict';
  const root=document.getElementById('rss-previews');
  if (!root) return;
  try {
    const res=await fetch('/blog/catalog.json',{cache:'no-cache'});
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data=await res.json();
    const records=(data.posts||[]).filter(x=>x.published===true).slice(0,8);
    const used=new Set();
    for (const p of records) {
      if (used.has(p.thumb)) continue;
      used.add(p.thumb);
      const card=document.createElement('article');card.className='tile';
      if (/^\/assets\/hero\/[a-z0-9-]+\.png$/.test(p.thumb||'')) {
        const img=document.createElement('img'); img.src=p.thumb;img.alt=p.hero_alt||`Cover for ${p.title}`;img.loading='lazy';img.width=1920;img.height=1080;card.appendChild(img);
      }
      const body=document.createElement('div');body.className='body';
      const title=document.createElement('h3');const link=document.createElement('a');
      link.href=p.url;link.textContent=p.title;title.appendChild(link);body.appendChild(title);
      const d=document.createElement('p');d.textContent=p.description||'';body.appendChild(d);
      card.appendChild(body);root.appendChild(card);
    }
    document.getElementById('rss-count').textContent=`${records.length} recent items`;
    if (!records.length){const p=document.createElement('p');p.textContent='No verified publications in the supplied site snapshot yet.';root.appendChild(p);}
  }catch(e){const p=document.createElement('p');p.textContent='RSS previews are unavailable. You may still open the RSS XML feed.';root.appendChild(p);}
})();
